package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"sort"
	"strings"
	"sync"
	"time"
)

// NodeInfo holds the IDs generated by a node globally across the cluster
type NodeInfo struct {
	NodeID  string      `json:"node_id"`
	IDs     []string    `json:"ids,omitempty"` // For tracking used IDs
}

// GlobalState tracks all IDs from this node's perspective
var (
	globalIDSet = make(map[string]bool)
	nodeIDs     = make(map[string]NodeInfo)
	mu          sync.RWMutex
	leaderNode  = ""
	isLeader    bool
)

// Message structure for stdin communication
type InMessage struct {
	Type string `json:"type"`
	Src   string `json:"src,omitempty"`
	Dest string `json:"dest,omitempty"`
	Body map[string]any `json:"body"`
}

// Generate request/response structures
type GenerateRequest struct {
	InMsg     InMessage    `json:"in_msg"`
	OrigMsgID int          `json:"msg_id,omitempty"`
}

type GenerateResponse struct {
	InReplyTo   int      `json:"in_reply_to"`
	ID          string   `json:"id"`
	MsgID       int      `json:"msg_id"` // Original request ID for correlation
	TimestampMs int64    `json:"timestamp_ms"`
}

func init() {
	log.SetFlags(log.LstdFlags | log.Lmicroseconds)
	go runClusterCoordinator()
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := os.Stdout

	// Handle special messages on stdin for cluster coordination
	scanner := bufio.NewScanner(reader)
	for scanner.Scan() {
		line := scanner.Text()
		if line == "init" || strings.HasPrefix(line, "init:") {
			continue
		}
	}

	// Actually, we use maelstrom's library to handle messages properly
	// But let's set up the initial coordination logic

	// Create a goroutine to run message handling loop
	go func() {
		defer writer.Close()

		for {
			if nodeID := getMyNodeID(); nodeID != "" {
				log.Printf("[%s] Node initialized", nodeID)

				msgLine, err := reader.ReadBytes('\n')
				if err == io.EOF {
					return
				}
				log.Printf("[%s] Read: %s", nodeID, string(msgLine))
			}
		}
	}()

	writer.Close()
}

// Run the cluster coordinator that handles ID generation and synchronization
func runClusterCoordinator() {
	ticker := time.NewTicker(5 * time.Second)
	defer ticker.Stop()

	for range ticker.C {
		mu.RLock()
		var leader string
		if len(nodeIDs) > 0 {
			sortedIds := make([]string, 0, len(nodeIDs))
			for id := range nodeIDs {
				sortedIds = append(sortedIds, id)
			}
			sort.Strings(sortedIds)
			leader = sortedIds[len(sortedIds)/2]
		}
		mu.RUnlock()

		if leader == "" {
			continue
		}

		log.Printf("[%s] Current leader: %s", getMyNodeID(), leader)

		// Try to sync with other nodes
		syncWithOtherNodes(leader)
	}
}

func getMyNodeID() string {
	mu.RLock()
	defer mu.RUnlock()

	for _, info := range nodeIDs {
		if info.NodeID == "self" || info.NodeID == getEnv("NODE_ID") {
			return info.NodeID
		}
	}

	return ""
}

func getEnv(name string) string {
	split := strings.SplitN(name, "_", 2)
	key := split[0]
	value := os.Getenv(key)
	return value
}

// Sync state with the leader node to ensure consistency
func syncWithOtherNodes(leader string) {
	mu.Lock()

	if leader != "" && leader != getMyNodeID() {
		syncRequest := &SyncRequest{
			NodeID: getMyNodeID(),
			MyIDs:  cloneMap(&globalIDSet),
		}

		log.Printf("[%s] Syncing with %s", getMyNodeID(), leader)

		client := newClient()
		resp, err := client.sendSync(getMyNodeID(), leader, syncRequest)

		if err != nil {
			log.Printf("[%s] Sync error: %v", getMyNodeID(), err)
		} else if resp.Error != "" {
			log.Printf("[%s] Received error from %s: %s", getMyNodeID(), leader, resp.Error)
		} else {
			log.Printf("[%s] Sync response: has %d more IDs", getMyNodeID(), len(resp.HasMoreIDs))
			for i, id := range resp.HasMoreIDs {
				if globalIDSet[id] {
					log.Printf("[%s] ID conflict! Skipping duplicate: %s", getMyNodeID(), id)
				} else {
					globalIDSet[id] = true
				}
			}
		}
		client.Close()
		mu.Unlock()
	}
}

// Simple mock client for sending sync requests
type Client struct {
	addr   string
	reader *bufio.Reader
	writer *os.File
	closed bool
}

func newClient() *Client {
	return &Client{} // Simplified - will be implemented with proper transport
}

func (c *Client) sendSync(from, to string, data any) (*SyncResponse, error) {
	// For the maelstrom integration, we'd use actual JSON RPC here
