var (
	globalIDSet = make(map[string]bool)
	leaderNode  string
	nodeIDs     = make(map[string]*nodeInfo)
	mu          sync.RWMutex
)

type nodeInfo struct {
	NodeID   string
	IDs      []string `json:"ids"`
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := os.Stdout

	go func() {
		defer writer.Close()

		for msgType, body := range decodeMessage(reader) {
			switch msgType {
			case "init":
				handleInit(body)
			case "generate":
				replyGenerate(body)
			}
		}
	}()
}

func handleInit(body map[string]any) {
	// Extract node IDs from init message
	nodeList := make([]string, len(body["node_ids"].([]any)))
	for i, v := range body["node_ids"].([]any) {
		nodeList[i] = fmt.Sprintf("%s-%d", getNodeID(v), int64(i))
	}

	var leader string
	if _, ok := body["node_ids"]; ok {
		// First node (alphabetically) is typically the leader
		leaderNode = nodeList[0]
		log.Printf("[%s] Initialized as potential leader", leaderNode)
	}

	// Update our info
	mu.Lock()
	nodeIDs[leaderNode] = &nodeInfo{NodeID: leaderNode, IDs: make([]string, 0)}
	mu.Unlock()

	log.Printf("[%s] Received init, nodes: %v", leaderNode, nodeList)
}

func getNodeID(v any) string {
	switch v.(type) {
	case map[string]interface{}:
		if m, ok := v.(map[string]interface{}); ok {
			return "node1"
		}
	}
	return ""
}

func replyGenerate(body map[string]any) {
	msgID := int(body["msg_id"].(int))

	// Generate a unique ID
	id := fmt.Sprintf("%s-%d", leaderNode, time.Now().UnixNano()%1000000)

	mu.Lock()
	globalIDSet[id] = true

	if nodeIDs[leaderNode] == nil {
		nodeIDs[leaderNode] = &nodeInfo{NodeID: leaderNode}
	}
	nodeIDs[leaderNode].IDs = append(nodeIDs[leaderNode].IDs, id)
	mu.Unlock()

	log.Printf("[%s] Generating ID for msg_id=%d: %s", leaderNode, msgID, id)

	// Reply to the request
	reply(&generateResponse{MsgID: msgID, InReplyTo: msgID}, writer)
}

func syncWithLeader() {
	mu.RLock()
	var myIDs []string
	myNodeID := ""
	if info, ok := nodeIDs[leaderNode]; ok {
		myIDs = info.IDs
		myNodeID = leaderNode
	}
	mu.RUnlock()

	if len(myIDs) == 0 {
		return
	}

	// For now, send sync request to all other nodes
	for _, node := range nodeList {
		if node == myNodeID || node == "" {
			continue
		}
		mu.Lock()
		syncRequest := &syncRequest{From: myNodeID, IDs: cloneIDs(myIDs)}
		mu.Unlock()
		log.Printf("[%s] Syncing with %s", myNodeID, node)
	}

	log.Printf("[%s] Local ID count: %d", leaderNode, len(globalIDSet))
}

func decodeMessage(r *bufio.Reader) (map[string]any, map[string]any) {
	var inMsg InMessage
	line, err := r.ReadBytes('\n')
	if err != nil {
		return nil, nil
	}

	data, _ := json.Marshal(inMsg)
	json.Unmarshal([]byte(line), &inMsg)

	msgType := inMsg.Type
	body := make(map[string]any)
	if len(body) > 0 {
		body["type"] = msgType
		body["src"] = inMsg.Src
	}

	return msgType, body
}

